const markTyping = (field: keyof typeof MANUAL_MARK_KEYS) => {
  const digits = MANUAL_MARK_KEYS[field];
  const page = `mark-manual-${field}`;
  return typing(field, digits, [...digits].map((_, i) => `${page}-${i + 1}`).concat(`${page}-done`));
};

